import{createFrameLighting}from'./original-frame-lighting.mjs';
import{prepareForestRegion}from'./provider.mjs';import{FOREST}from'./registration.mjs';
const MANIFEST_SHA='3f337223b51724f825810ff0a15a6eecbb02897a1202f836342f35a9272ff4cc';const hash=async b=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',b))].map(v=>v.toString(16).padStart(2,'0')).join('');
const direction={down:'FRONT',right:'RIGHT',left:'LEFT',up:'BACK'},ids=FOREST.actors.map(a=>a.sprite);
// NEW_REBUILD: exact approved source63 atlas frames; no generated actor, altered identity, or progression.
export async function prepareForestPresentation({signal,appearance='boy'}={}){
 if(!['boy','girl'].includes(appearance))throw Error('FOREST_PRESENTATION_SELECTION');let disposed=false,provider,native,actorCanvas,lastFrame=null,lastPose=null,lastVisual=null;const shade=createFrameLighting({nightTint:[.4,.47,.6]});const images=new Map;const check=()=>{if(disposed||signal?.aborted)throw Error('FOREST_PRESENTATION_ABORT')};
 const dispose=()=>{if(disposed)return;disposed=true;lastFrame=null;lastPose=null;lastVisual=null;provider?.dispose();for(const im of images.values())im.close();images.clear();if(native)native.width=native.height=1;native=null;if(actorCanvas)actorCanvas.width=actorCanvas.height=1;actorCanvas=null;signal?.removeEventListener('abort',dispose)};
 const read=async(url,pin)=>{check();const res=await fetch(url,{signal});if(!res.ok)throw Error('FOREST_ATLAS_HTTP');const bytes=await res.arrayBuffer();check();if(await hash(bytes)!==pin)throw Error('FOREST_ATLAS_PIN');return bytes};
 try{provider=await prepareForestRegion({signal});const manifestURL=new URL('../../assets/approved-atlases/manifest.json',import.meta.url),manifest=JSON.parse(new TextDecoder().decode(await read(manifestURL,MANIFEST_SHA))),playerId=appearance==='girl'?'PLAYER_FEMALE':'PLAYER_MALE';
 for(const key of[...ids.map(x=>'npc/'+x),'player/'+playerId]){const pin=manifest.atlases[key],bytes=await read(new URL('../../'+pin.src,import.meta.url),pin.sha256),image=await createImageBitmap(new Blob([bytes],{type:'image/png'}));if(disposed||signal?.aborted){image.close();throw Error('FOREST_PRESENTATION_ABORT')}images.set(key,image)}
 check();native=new OffscreenCanvas(...provider.registration.size);const ctx=native.getContext('2d');signal?.addEventListener('abort',dispose,{once:true});
 function actor(key,kind,foot,facing,step,nightMix){const frame=manifest.frames[kind][`${key}.${direction[facing]}.${step}`];if(!frame)throw Error('FOREST_ACTOR_FRAME');const sc=80/192;if(!actorCanvas)actorCanvas=new OffscreenCanvas(frame.width,frame.height);actorCanvas.width=frame.width;actorCanvas.height=frame.height;const ac=actorCanvas.getContext('2d');ac.drawImage(images.get(frame.atlas),...frame.rect,0,0,frame.width,frame.height);const pixels=ac.getImageData(0,0,frame.width,frame.height);shade(pixels.data,pixels.data,nightMix);ac.putImageData(pixels,0,0);ctx.drawImage(actorCanvas,foot[0]-frame.anchor[0]*sc,foot[1]-frame.anchor[1]*sc,frame.width*sc,frame.height*sc)}
 function draw(destination,{foot,facing,state,elapsedMs=0,moving=false,nightMix=0,lightsEnabled=true,npcFacings={}}={}){lastFrame=null;lastPose=null;lastVisual=null;if(disposed)return false;provider.describe(foot,facing);if(!Number.isFinite(elapsedMs)||elapsedMs<0)throw Error('FOREST_ELAPSED_TIME');ctx.clearRect(0,0,native.width,native.height);provider.draw(ctx,{nightMix,lights:lightsEnabled});const background=provider.currentFrame();const actors=FOREST.actors.map(a=>({...a,key:a.sprite,kind:'npc',facing:direction[npcFacings[a.id]]?npcFacings[a.id]:a.facing,step:'IDLE'}));actors.push({id:'player',key:playerId,kind:'player',foot:[...foot],facing,step:moving?['A','IDLE','B','IDLE'][Math.floor(elapsedMs/140)%4]:'IDLE'});actors.sort((a,b)=>a.foot[1]-b.foot[1]);for(const a of actors){actor(a.key,a.kind,a.foot,a.facing,a.step,nightMix);provider.restoreForeground(ctx,background,a.foot)}const w=destination.canvas.width,h=destination.canvas.height,cx=Math.max(0,Math.min(native.width-w,foot[0]-w/2)),cy=Math.max(0,Math.min(native.height-h,foot[1]-h/2));destination.save();try{destination.imageSmoothingEnabled=false;destination.clearRect(0,0,w,h);destination.drawImage(native,cx,cy,w,h,0,0,w,h)}finally{destination.restore()}lastPose=provider.describe(foot,facing);lastVisual={elapsedMs,nightMix,lightsEnabled};lastFrame=Object.freeze({});return true}
 return Object.freeze({get pinsVerified(){return!disposed},currentFrame:()=>lastFrame,frameMatchesPose:(token,pose,elapsedMs,nightMix,lightsEnabled)=>{if(disposed||!lastFrame||token!==lastFrame||!provider.validate(pose)||!lastVisual)return false;return pose.foot[0]===lastPose.foot[0]&&pose.foot[1]===lastPose.foot[1]&&pose.facing===lastPose.facing&&elapsedMs===lastVisual.elapsedMs&&nightMix===lastVisual.nightMix&&lightsEnabled===lastVisual.lightsEnabled},registration:provider.registration,safe:provider.safe,validate:provider.validate,describe:provider.describe,contact:provider.contact,resolveContact:provider.resolveContact,wildZone:provider.wildZone,draw,dispose});
 }catch(e){dispose();throw e}
}
